import re,os,glob
files=['README.md','ROUTER.md','SKILL.md','assets/question-shaping-card.md']+glob.glob('references/*.md')
for f in files:
    t=open(f).read()
    for m in re.finditer(r'\[[^\]]*\]\(([^)]+)\)',t):
        tgt=m.group(1)
        if tgt.startswith('http') or tgt.startswith('#'): continue
        p=os.path.normpath(os.path.join(os.path.dirname(f),tgt.split('#')[0]))
        if not os.path.exists(p): print(f,'BROKEN',tgt,'->',p)
print('done')
EOF"}

